import { defineRailway, github, postgres, project, service, volume } from "railway/iac";

// Railway Infrastructure as Code for the whole Haber-Process-Railway project.
// Generated by `railway config migrate` from railway.json, then completed from
// `railway config pull`. Variables (Odds API keys etc.) stay unmanaged and live
// only on Railway. Preview changes with `railway config plan` (read-only).
export default defineRailway(() => {
  // The app's database. Its DATABASE_URL reaches the web service as a variable (unmanaged, set on Railway).
  const db = postgres("Postgres");

  // The ESPN cache lives here (backend/data), and the SQLite database the app used before Postgres.
  const data = volume("nfl-prop-predictor-volume", {
    alerts: { usage: { "100": {}, "80": {}, "95": {} } },
    allowOnlineResize: true,
    region: "iad",
    sizeMB: 500,
  });

  const web = service("Haber Process", {
    source: github("JoshuaDHaber/NFL-Prop-Predictor", { branch: "main", checkSuites: false }),
    build: { buildEnvironment: "V3", builder: "DOCKERFILE", dockerfilePath: "Dockerfile" },
    healthcheck: "/healthz",
    healthcheckTimeout: 120,
    deploy: { restartPolicyType: "ON_FAILURE" },
    replicas: { iad: 1 },
    domains: ["process.jdhaber.com"],
    networking: { privateNetworkEndpoint: "nfl-prop-predictor" },
    volumeMounts: { "/srv/backend/data": data },
  });

  return project("Haber-Process-Railway", {
    // Unmanaged: the CLI reads this, though the SDK 3.16 types do not list it yet.
    variables: { managed: false },
    resources: [web, data, db],
  });
});
